const dns = require('dns');
const dgram = require('dgram');
const fs = require('fs');

// Create a simple DNS query packet for our specific use case
function createDnsQuery(name) {
  const packet = Buffer.alloc(512);
  let offset = 0;

  // Header (12 bytes)
  packet.writeUInt16BE(0x1234, 0); // Transaction ID
  packet.writeUInt16BE(0x0100, 2); // Flags (standard query)
  packet.writeUInt16BE(0x0001, 4); // Questions
  packet.writeUInt16BE(0x0000, 6); // Answer RRs
  packet.writeUInt16BE(0x0000, 8); // Authority RRs
  packet.writeUInt16BE(0x0000, 10); // Additional RRs
  offset = 12;

  // Question section
  const labels = name.split('.');
  for (const label of labels) {
    packet.writeUInt8(label.length, offset++);
    Buffer.from(label).copy(packet, offset);
    offset += label.length;
  }
  packet.writeUInt8(0, offset++); // End of domain name
  packet.writeUInt16BE(0x0010, offset); // Type TXT
  offset += 2;
  packet.writeUInt16BE(0x0001, offset); // Class IN
  offset += 2;

  return packet.slice(0, offset);
}

// Get the DATABASE_URL from .env.test and process it properly
