// Proper base32 encoding - simplified version
// Note: This isn't a complete base32 implementation but should work for our purposes
function toBase32(str) {
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ234567';
  let bits = '';
  let result = '';

  // Convert each character to binary representation
  for (let i = 0; i < str.length; i++) {
    let bin = str.charCodeAt(i).toString(2);
    // Pad to 8 bits
    while (bin.length < 8) bin = '0' + bin;
    bits += bin;
  }

  // Process 5 bits at a time
  for (let i = 0; i < bits.length; i += 5) {
    let chunk = bits.substr(i, 5);
    if (chunk.length < 5) {
      // Pad with zeros
      while (chunk.length < 5) chunk += '0';
    }
    const index = parseInt(chunk, 2);
    result += alphabet[index];
  }

  return result;
}

const base32Encoded = toBase32(databaseUrl);
