// Send DNS query to localhost:47302
const client = dgram.createSocket('udp4');
const message = createDnsQuery(hostname);

client.send(message, 47302, 'localhost', (err) => {
  if (err) {
    console.error('Error sending DNS query:', err);
    client.close();
  } else {
